use crate::model::*;
use std::collections::BTreeSet;
use std::fmt::Write as _;

#[derive(Clone, Debug)]
pub struct Val { pub ty: Ty, pub v: String }
#[derive(Clone)]
struct Frame {
    kind: u32, height: usize, params: Vec<Ty>, results: Vec<Ty>, saved: Vec<Val>,
    slots: Vec<String>, label: String, end: String, other: String,
    outer: bool, used: bool, had_else: bool,
}
pub struct Emitter<'a> {
    pub m: &'a Module, pub body: String, allocas: String, pub decls: BTreeSet<String>,
    next: usize, stack: Vec<Val>, frames: Vec<Frame>, live: bool,
}
pub fn hex(s: &str)->String { s.as_bytes().iter().map(|b|format!("{b:02x}")).collect() }
fn ret_type(t:&FuncType)->String { match t.results.len() {0=>"void".into(),1=>t.results[0].llvm().into(),_=>format!("{{ {} }}",t.results.iter().map(|t|t.llvm()).collect::<Vec<_>>().join(", "))} }
fn signature(t:&FuncType)->String {t.params.iter().enumerate().map(|(j,t)|format!("{} %a{j}",t.llvm())).collect::<Vec<_>>().join(", ")}
fn type_id(m:&Module,idx:u32)->usize {m.types.iter().position(|t|*t==m.types[idx as usize]).unwrap()}
impl<'a> Emitter<'a> {
    fn new(m:&'a Module)->Self {Self{m,body:String::new(),allocas:String::new(),decls:BTreeSet::new(),next:0,stack:vec![],frames:vec![],live:true}}
    fn name(&mut self)->String { let n=self.next;self.next+=1;format!("%v{n}") }
    fn label(&mut self)->String {let n=self.next;self.next+=1;format!("b{n}")}
    pub fn line(&mut self,s:impl Into<String>) {writeln!(self.body,"  {}",s.into()).unwrap();}
    fn mark(&mut self,l:&str) {writeln!(self.body,"{l}:").unwrap();}
    pub fn raw(&mut self,s:impl Into<String>)->String {let v=self.name();self.line(format!("{v} = {}",s.into()));v}
    pub fn value(&mut self,ty:Ty,s:impl Into<String>)->Val {Val{ty,v:self.raw(s)}}
    pub fn declare(&mut self,s:impl Into<String>) {self.decls.insert(s.into());}
    pub fn pop(&mut self,t:Ty)->Result<Val,String> {let v=self.stack.pop().ok_or("lowering stack underflow")?;if v.ty!=t{return Err("lowering type mismatch".into())}Ok(v)}
    fn any(&mut self)->Result<Val,String> {self.stack.pop().ok_or("lowering stack underflow".into())}
    pub fn push(&mut self,v:Val) {self.stack.push(v)}
    fn alloca(&mut self,t:&str)->String {let v=self.name();writeln!(self.allocas,"  {v} = alloca {t}, align 16").unwrap();v}
    pub fn check(&mut self,cond:&str,code:u32) {let bad=self.label();let ok=self.label();self.line(format!("br i1 {cond}, label %{bad}, label %{ok}"));self.mark(&bad);self.line(format!("call void @trap(i32 {code})"));self.line("unreachable");self.mark(&ok);}
    pub fn mem_ptr(&mut self,addr:&Val,offset:u64,size:u64)->Result<String,String> {
        if self.m.memory.is_none(){return Err("memory instruction without memory".into())}
        let a=self.raw(format!("zext i32 {} to i64",addr.v));let a=if offset==0{a}else{self.raw(format!("add i64 {a}, {offset}"))};
        let end=self.raw(format!("add i64 {a}, {size}"));let len=self.raw("load i64, ptr @mem.size");let bad=self.raw(format!("icmp ugt i64 {end}, {len}"));self.check(&bad,4);
        let base=self.raw("load ptr, ptr @mem.base");Ok(self.raw(format!("getelementptr i8, ptr {base}, i64 {a}")))
    }
    fn range(&mut self,addr:&Val,n:&Val,len:&str,code:u32)->String {
        let a=self.raw(format!("zext i32 {} to i64",addr.v));let n=self.raw(format!("zext i32 {} to i64",n.v));let end=self.raw(format!("add i64 {a}, {n}"));let bad=self.raw(format!("icmp ugt i64 {end}, {len}"));self.check(&bad,code);a
    }
    fn take(&mut self,ts:&[Ty])->Result<Vec<Val>,String> {let mut v=Vec::new();for t in ts.iter().rev(){v.push(self.pop(*t)?)}v.reverse();Ok(v)}
    fn peek(&self,ts:&[Ty])->Vec<Val> {self.stack[self.stack.len()-ts.len()..].to_vec()}
    fn stores(&mut self,vs:&[Val],slots:&[String]) {for (v,p) in vs.iter().zip(slots){self.line(format!("store {} {}, ptr {p}, align 1",v.ty.llvm(),v.v));}}
    fn loads(&mut self,ts:&[Ty],slots:&[String])->Vec<Val> {ts.iter().zip(slots).map(|(t,p)|self.value(*t,format!("load {}, ptr {p}, align 1",t.llvm()))).collect()}
    fn block_type(&self,i:&Instr)->(Vec<Ty>,Vec<Ty>) {match i.imm {-64=>(vec![],vec![]),-1=>(vec![],vec![Ty::I32]),-2=>(vec![],vec![Ty::I64]),-3=>(vec![],vec![Ty::F32]),-4=>(vec![],vec![Ty::F64]),-5=>(vec![],vec![Ty::V128]),n=>{let t=&self.m.types[n as usize];(t.params.clone(),t.results.clone())}}}
    fn begin(&mut self,i:&Instr)->Result<(),String> {
        let (params,results)=self.block_type(i);let outer=self.live;
        let cond=if outer&&i.op==4{Some(self.pop(Ty::I32)?)}else{None};
        let saved=if outer {self.take(&params)?}else{vec![]};let height=self.stack.len();
        let label=self.label();let end=self.label();let other=self.label();
        let slot_types=if i.op==3{&params}else{&results};let slots=slot_types.iter().map(|t|self.alloca(t.llvm())).collect::<Vec<_>>();
        if outer {
            if i.op==3 {self.stores(&saved,&slots);self.line(format!("br label %{label}"));self.mark(&label);let vals=self.loads(&params,&slots);self.stack.extend(vals);}
            else {self.stack.extend(saved.clone());if let Some(c)=cond{let c=self.raw(format!("icmp ne i32 {}, 0",c.v));self.line(format!("br i1 {c}, label %{label}, label %{other}"));self.mark(&label);}}
        }
        self.frames.push(Frame{kind:i.op,height,params,results,saved,slots,label,end,other,outer,used:false,had_else:false});Ok(())
    }
    fn end(&mut self,is_else:bool)->Result<(),String> {
        let mut f=self.frames.pop().ok_or("bad control frame")?;
        if self.live {let vs=self.take(&f.results)?; if f.kind==3 {
            // Loops branch to parameters, but fall through with results.
            let slots=f.results.iter().map(|t|self.alloca(t.llvm())).collect::<Vec<_>>();self.stores(&vs,&slots);f.slots=slots;
        } else {self.stores(&vs,&f.slots)} self.line(format!("br label %{}",f.end));f.used=true;}
        self.stack.truncate(f.height);
        if is_else {
            self.mark(&f.other);self.live=f.outer;self.stack.extend(f.saved.clone());f.had_else=true;self.frames.push(f);return Ok(())
        }
        if f.kind==4&&!f.had_else {
            self.mark(&f.other);if f.outer{self.stores(&f.saved,&f.slots);self.line(format!("br label %{}",f.end));f.used=true;}
            else {self.line("unreachable");}
        }
        self.live=f.used;
        // A loop's backedges do not make its end reachable.
        self.mark(&f.end);
        if self.live {let vals=self.loads(&f.results,&f.slots);self.stack.extend(vals);}else{self.line("unreachable");}
        Ok(())
    }
    fn branch(&mut self,depth:u32,conditional:Option<Val>)->Result<(),String> {
        let idx=self.frames.len()-1-depth as usize;let f=self.frames[idx].clone();
        let ts=if f.kind==3{&f.params}else{&f.results};let vs=self.peek(ts);self.stores(&vs,&f.slots);
        let target=if f.kind==3{f.label}else{self.frames[idx].used=true;f.end};
        if let Some(c)=conditional {let c=self.raw(format!("icmp ne i32 {}, 0",c.v));let cont=self.label();self.line(format!("br i1 {c}, label %{target}, label %{cont}"));self.mark(&cont);}
        else{self.line(format!("br label %{target}"));self.live=false;}
        Ok(())
    }
    fn call(&mut self,t:&FuncType,callee:&str)->Result<(),String> {
        let vs=self.take(&t.params)?;let args=vs.iter().map(|v|format!("{} {}",v.ty.llvm(),v.v)).collect::<Vec<_>>().join(", ");let rt=ret_type(t);
        if t.results.is_empty(){self.line(format!("call {rt} {callee}({args})"));}
        else{let v=self.raw(format!("call {rt} {callee}({args})"));if t.results.len()==1{self.push(Val{ty:t.results[0],v})}else{for (j,ty) in t.results.iter().enumerate(){let r=self.value(*ty,format!("extractvalue {rt} {v}, {j}"));self.push(r)}}}
        Ok(())
    }
    fn instr(&mut self,i:&Instr)->Result<(),String> {
        match i.op {2|3|4=>return self.begin(i),5=>return self.end(true),11=>return self.end(false),_=>{}}
        if !self.live{return Ok(())}
        match i.op {
            0=>{self.line("call void @trap(i32 0)");self.line("unreachable");self.live=false;},1=>{},
            12=>self.branch(i.a,None)?,13=>{let c=self.pop(Ty::I32)?;self.branch(i.a,Some(c))?;},
            14=>{let c=self.pop(Ty::I32)?;let default=self.label();let labels=(0..i.list.len()).map(|_|self.label()).collect::<Vec<_>>();let cases=labels.iter().enumerate().map(|(j,l)|format!("i32 {j}, label %{l}")).collect::<Vec<_>>().join(" ");self.line(format!("switch i32 {}, label %{default} [ {cases} ]",c.v));for (&d,l) in i.list.iter().zip(&labels){self.mark(l);self.branch(d,None)?;}self.mark(&default);self.branch(i.a,None)?;},
            15=>self.branch((self.frames.len()-1) as u32,None)?,
            16=>{let t=self.m.types[self.m.funcs[i.a as usize].type_idx as usize].clone();self.call(&t,&format!("@f{}",i.a))?;},
            17=>{let idx=self.pop(Ty::I32)?;let x=self.raw(format!("zext i32 {} to i64",idx.v));let lim=self.m.table.as_ref().unwrap().min;let bad=self.raw(format!("icmp uge i64 {x}, {lim}"));self.check(&bad,5);let base=self.raw("load ptr, ptr @table.base");let p=self.raw(format!("getelementptr i32, ptr {base}, i64 {x}"));let id=self.raw(format!("load i32, ptr {p}, align 4"));let null=self.raw(format!("icmp eq i32 {id}, 0"));self.check(&null,6);let fi=self.raw(format!("sub i32 {id}, 1"));let tp=self.raw(format!("getelementptr [{} x i32], ptr @func.types, i32 0, i32 {fi}",self.m.funcs.len()));let ty=self.raw(format!("load i32, ptr {tp}"));let mismatch=self.raw(format!("icmp ne i32 {ty}, {}",type_id(self.m,i.a)));self.check(&mismatch,7);let pp=self.raw(format!("getelementptr [{} x ptr], ptr @func.ptrs, i32 0, i32 {fi}",self.m.funcs.len()));let fun=self.raw(format!("load ptr, ptr {pp}"));let t=self.m.types[i.a as usize].clone();self.call(&t,&fun)?;},
            26=>{self.any()?;},27=>{let c=self.pop(Ty::I32)?;let b=self.any()?;let a=self.pop(b.ty)?;let c=self.raw(format!("icmp ne i32 {}, 0",c.v));let v=self.value(a.ty,format!("select i1 {c}, {} {}, {} {}",a.ty.llvm(),a.v,b.ty.llvm(),b.v));self.push(v);},
            32=>{let ty=self.local_type(i.a);let v=self.value(ty,format!("load {}, ptr %l{}, align 1",ty.llvm(),i.a));self.push(v);},
            33|34=>{let ty=self.local_type(i.a);let v=self.pop(ty)?;self.line(format!("store {} {}, ptr %l{}, align 1",ty.llvm(),v.v,i.a));if i.op==34{self.push(v)}},
            35=>{let ty=self.m.globals[i.a as usize].ty;let v=self.value(ty,format!("load {}, ptr @g{}",ty.llvm(),i.a));self.push(v);},
            36=>{let ty=self.m.globals[i.a as usize].ty;let v=self.pop(ty)?;self.line(format!("store {} {}, ptr @g{}",ty.llvm(),v.v,i.a));},
            40..=62=>self.memory(i)?,
