            64=>{let n=self.pop(Ty::I32)?;let v=self.value(Ty::I32,format!("call i32 @memory.grow(i32 {})",n.v));self.push(v);},
            65=>self.push(Val{ty:Ty::I32,v:(i.imm as i32).to_string()}),66=>self.push(Val{ty:Ty::I64,v:i.imm.to_string()}),
