use crate::model::*;
use std::collections::BTreeSet;
use std::fmt::Write as _;

#[derive(Clone, Debug)]
pub struct Val { pub ty: Ty, pub v: String }
#[derive(Clone)]
struct Frame {
    kind: u32, height: usize, params: Vec<Ty>, results: Vec<Ty>, saved: Vec<Val>,
    slots: Vec<String>, label: String, end: String, other: String,
    outer: bool, used: bool, had_else: bool,
}
pub struct Emitter<'a> {
    pub m: &'a Module, pub body: String, allocas: String, pub decls: BTreeSet<String>,
    next: usize, stack: Vec<Val>, frames: Vec<Frame>, live: bool,
}
pub fn hex(s: &str)->String { s.as_bytes().iter().map(|b|format!("{b:02x}")).collect() }
fn ret_type(t:&FuncType)->String { match t.results.len() {0=>"void".into(),1=>t.results[0].llvm().into(),_=>format!("{{ {} }}",t.results.iter().map(|t|t.llvm()).collect::<Vec<_>>().join(", "))} }
fn signature(t:&FuncType)->String {t.params.iter().enumerate().map(|(j,t)|format!("{} %a{j}",t.llvm())).collect::<Vec<_>>().join(", ")}
fn type_id(m:&Module,idx:u32)->usize {m.types.iter().position(|t|*t==m.types[idx as usize]).unwrap()}
impl<'a> Emitter<'a> {
    fn new(m:&'a Module)->Self {Self{m,body:String::new(),allocas:String::new(),decls:BTreeSet::new(),next:0,stack:vec![],frames:vec![],live:true}}
    fn name(&mut self)->String { let n=self.next;self.next+=1;format!("%v{n}") }
    fn label(&mut self)->String {let n=self.next;self.next+=1;format!("b{n}")}
    pub fn line(&mut self,s:impl Into<String>) {writeln!(self.body,"  {}",s.into()).unwrap();}
    fn mark(&mut self,l:&str) {writeln!(self.body,"{l}:").unwrap();}
    pub fn raw(&mut self,s:impl Into<String>)->String {let v=self.name();self.line(format!("{v} = {}",s.into()));v}
    pub fn value(&mut self,ty:Ty,s:impl Into<String>)->Val {Val{ty,v:self.raw(s)}}
    pub fn declare(&mut self,s:impl Into<String>) {self.decls.insert(s.into());}
    pub fn pop(&mut self,t:Ty)->Result<Val,String> {let v=self.stack.pop().ok_or("lowering stack underflow")?;if v.ty!=t{return Err("lowering type mismatch".into())}Ok(v)}
    fn any(&mut self)->Result<Val,String> {self.stack.pop().ok_or("lowering stack underflow".into())}
    pub fn push(&mut self,v:Val) {self.stack.push(v)}
    fn alloca(&mut self,t:&str)->String {let v=self.name();writeln!(self.allocas,"  {v} = alloca {t}, align 16").unwrap();v}
    pub fn check(&mut self,cond:&str,code:u32) {let bad=self.label();let ok=self.label();self.line(format!("br i1 {cond}, label %{bad}, label %{ok}"));self.mark(&bad);self.line(format!("call void @trap(i32 {code})"));self.line("unreachable");self.mark(&ok);}
    pub fn mem_ptr(&mut self,addr:&Val,offset:u64,size:u64)->Result<String,String> {
        if self.m.memory.is_none(){return Err("memory instruction without memory".into())}
        let a=self.raw(format!("zext i32 {} to i64",addr.v));let a=if offset==0{a}else{self.raw(format!("add i64 {a}, {offset}"))};
        let end=self.raw(format!("add i64 {a}, {size}"));let len=self.raw("load i64, ptr @mem.size");let bad=self.raw(format!("icmp ugt i64 {end}, {len}"));self.check(&bad,4);
        let base=self.raw("load ptr, ptr @mem.base");Ok(self.raw(format!("getelementptr i8, ptr {base}, i64 {a}")))
    }
    fn range(&mut self,addr:&Val,n:&Val,len:&str,code:u32)->String {
        let a=self.raw(format!("zext i32 {} to i64",addr.v));let n=self.raw(format!("zext i32 {} to i64",n.v));let end=self.raw(format!("add i64 {a}, {n}"));let bad=self.raw(format!("icmp ugt i64 {end}, {len}"));self.check(&bad,code);a
