64	fn block_type(m: &Module, imm: i64) -> Result<FuncType> {
65	    let result = match imm {
66	        -64 => None, -1 => Some(I32), -2 => Some(I64), -3 => Some(F32), -4 => Some(F64), -5 => Some(V128),
