73	fn limits(l: &Limits, memory: bool) -> Result<()> {
74	    if l.max.is_some_and(|max| max < l.min) || (memory && (l.min > 65536 || l.max.is_some_and(|max| max > 65536))) {
75	        return Err("invalid limits".into());
76	    }
77	    Ok(())
78	}
