80	fn constant(code: &[Instr], ty: Ty) -> Result<()> {
81	    if code.len() != 2 || code[1].op != 0x0b {
82	        return Err("constant expression must contain exactly one constant and end".into());
83	    }
84	    let actual = match code[0].op {
85	        0x41 => I32, 0x42 => I64, 0x43 => F32, 0x44 => F64, 0xfd0c => V128,
86	        // Imported globals cannot be represented by the ABI, so global.get is never constant here.
87	        _ => return Err("invalid constant expression (extended const/reference operations unsupported)".into()),
