93	/// Validate every index, initializer, declaration, and instruction, including dead code.
94	pub fn validate(m: &Module) -> Result<()> {
95	    if let Some(l) = &m.memory { limits(l, true)?; }
96	    if let Some(l) = &m.table { limits(l, false)?; }
97	    if let Some(n) = m.data_count {
98	        if n as usize != m.data.len() { return Err("data count does not match data section".into()); }
99	    }
100	    let mut saw_defined = false;
101	    for f in &m.funcs {
102	        if f.type_idx as usize >= m.types.len() { return Err("unknown function type index".into()); }
103	        if f.import.is_some() {
104	            if saw_defined || !f.locals.is_empty() || !f.code.is_empty() { return Err("invalid imported function representation".into()); }
105	        } else { saw_defined = true; }
106	        if m.types[f.type_idx as usize].params.len().checked_add(f.locals.len()).is_none_or(|n| n > u32::MAX as usize) {
107	            return Err("too many function locals".into());
108	        }
109	    }
110	    for g in &m.globals { constant(&g.init, g.ty)?; }
111	    let mut names = HashSet::new();
112	    for e in &m.exports {
113	        if !names.insert(&e.name) { return Err("duplicate export name".into()); }
114	        let count = match e.kind {
115	            0 => m.funcs.len(), 1 => usize::from(m.table.is_some()), 2 => usize::from(m.memory.is_some()), 3 => m.globals.len(),
116	            _ => return Err("invalid export kind".into()),
117	        };
118	        if e.index as usize >= count { return Err("unknown export index".into()); }
119	    }
120	    if let Some(index) = m.start {
121	        let f = m.funcs.get(index as usize).ok_or("unknown start function index")?;
122	        let ty = &m.types[f.type_idx as usize];
123	        if !ty.params.is_empty() || !ty.results.is_empty() { return Err("start function must have type [] -> []".into()); }
124	    }
125	    for e in &m.elems {
126	        if e.passive && e.declarative { return Err("invalid element segment mode".into()); }
127	        if !e.passive && !e.declarative {
128	            if m.table.is_none() { return Err("active element segment requires a table".into()); }
129	            constant(&e.offset, I32)?;
130	        } else if !e.offset.is_empty() { return Err("passive/declarative element segment has an offset".into()); }
131	        for &f in &e.funcs {
132	            if f as usize >= m.funcs.len() { return Err("unknown function in element segment".into()); }
133	        }
134	    }
135	    for d in &m.data {
136	        if !d.passive {
137	            if m.memory.is_none() { return Err("active data segment requires a memory".into()); }
138	            constant(&d.offset, I32)?;
139	        } else if !d.offset.is_empty() { return Err("passive data segment has an offset".into()); }
140	    }
141	    for (index, f) in m.funcs.iter().enumerate() {
142	        if f.import.is_none() {
143	            validate_function(m, f).map_err(|e| format!("function {index}: {e}"))?;
144	        }
145	    }
146	    Ok(())
147	}
148	
149	struct Frame {
150	    kind: u32,
151	    start: Vec<Ty>,
152	    end: Vec<Ty>,
153	    height: usize,
154	    unreachable: bool,
155	}
156	struct Stack { vals: Vec<Option<Ty>>, ctrls: Vec<Frame> }
157	impl Stack {
158	    fn pop(&mut self, expected: Option<Ty>) -> Result<Option<Ty>> {
159	        let c = self.ctrls.last().ok_or("instruction after function end")?;
160	        if self.vals.len() == c.height && c.unreachable { return Ok(None); }
161	        if self.vals.len() <= c.height { return Err("operand stack underflow".into()); }
162	        let actual = self.vals.pop().unwrap();
163	        if actual.is_some() && expected.is_some() && actual != expected { return Err("operand type mismatch".into()); }
164	        Ok(actual)
165	    }
166	    fn pop_types(&mut self, types: &[Ty]) -> Result<()> {
167	        for &ty in types.iter().rev() { self.pop(Some(ty))?; }
168	        Ok(())
169	    }
170	    fn push_types(&mut self, types: &[Ty]) { self.vals.extend(types.iter().copied().map(Some)); }
171	    fn effect(&mut self, inputs: &[Ty], outputs: &[Ty]) -> Result<()> {
172	        self.pop_types(inputs)?; self.push_types(outputs); Ok(())
173	    }
174	    fn dead(&mut self) {
175	        let c = self.ctrls.last_mut().unwrap(); self.vals.truncate(c.height); c.unreachable = true;
176	    }
177	    fn label(&self, index: u32) -> Result<Vec<Ty>> {
178	        let c = self.ctrls.len().checked_sub(index as usize + 1).and_then(|i| self.ctrls.get(i)).ok_or("unknown branch label")?;
179	        Ok(if c.kind == 3 { c.start.clone() } else { c.end.clone() })
180	    }
181	    fn close(&mut self) -> Result<Frame> {
182	        let types = self.ctrls.last().ok_or("unexpected end")?.end.clone();
183	        self.pop_types(&types)?;
184	        let c = self.ctrls.pop().unwrap();
185	        if self.vals.len() != c.height { return Err("excess operands at control boundary".into()); }
186	        Ok(c)
187	    }
188	}
189	
190	fn memory(m: &Module) -> Result<()> {
191	    if m.memory.is_none() { Err("memory instruction requires a memory".into()) } else { Ok(()) }
192	}
193	fn table(m: &Module) -> Result<()> {
194	    if m.table.is_none() { Err("table instruction requires a table".into()) } else { Ok(()) }
195	}
196	fn align(i: &Instr, max: u32) -> Result<()> {
197	    if i.a > max { Err("memory alignment exceeds natural alignment".into()) } else { Ok(()) }
198	}
199	fn lane(i: &Instr, count: i64) -> Result<()> {
200	    if i.imm < 0 || i.imm >= count { Err("SIMD lane index out of range".into()) } else { Ok(()) }
201	}
202	
203	fn validate_function(m: &Module, f: &Func) -> Result<()> {
204	    let ty = &m.types[f.type_idx as usize];
205	    let mut locals = ty.params.clone(); locals.extend_from_slice(&f.locals);
206	    let mut s = Stack { vals: vec![], ctrls: vec![Frame { kind: 0xff, start: vec![], end: ty.results.clone(), height: 0, unreachable: false }] };
207	    for (pc, i) in f.code.iter().enumerate() {
208	        if s.ctrls.is_empty() { return Err("instruction after function end".into()); }
209	        match i.op {
210	            0x00 => s.dead(), 0x01 => (),
211	            0x02..=0x04 => {
212	                let bt = block_type(m, i.imm)?;
213	                if i.op == 4 { s.pop(Some(I32))?; }
214	                s.pop_types(&bt.params)?;
215	                s.ctrls.push(Frame { kind: i.op, start: bt.params.clone(), end: bt.results, height: s.vals.len(), unreachable: false });
216	                s.push_types(&bt.params);
217	            }
218	            0x05 => {
219	                if s.ctrls.last().unwrap().kind != 4 { return Err("else without matching if, or duplicate else".into()); }
220	                let c = s.close()?;
221	                s.push_types(&c.start);
222	                s.ctrls.push(Frame { kind: 5, start: c.start, end: c.end, height: c.height, unreachable: false });
223	            }
224	            0x0b => {
225	                let c = s.close()?;
226	                if c.kind == 4 && c.start != c.end { return Err("if without else requires identical parameter/result types".into()); }
227	                s.push_types(&c.end);
228	                if s.ctrls.is_empty() && pc + 1 != f.code.len() { return Err("instructions after function end".into()); }
229	            }
230	            0x0c => { let types = s.label(i.a)?; s.pop_types(&types)?; s.dead(); }
231	            0x0d => { let types = s.label(i.a)?; s.pop(Some(I32))?; s.pop_types(&types)?; s.push_types(&types); }
232	            0x0e => {
233	                s.pop(Some(I32))?;
234	                let default = s.label(i.a)?;
235	                for &index in &i.list {
236	                    let types = s.label(index)?;
237	                    if types.len() != default.len() { return Err("br_table target arities differ".into()); }
238	                    // Preserve actual unknowns: in unreachable code equal arity, differing
239	                    // label types can be valid when every argument is polymorphic.
240	                    let mut actual = Vec::with_capacity(types.len());
241	                    for &t in types.iter().rev() { actual.push(s.pop(Some(t))?); }
242	                    s.vals.extend(actual.into_iter().rev());
243	                }
244	                s.pop_types(&default)?; s.dead();
245	            }
246	            0x0f => { s.pop_types(&ty.results)?; s.dead(); }
247	            0x10 | 0x11 => {
248	                let called = if i.op == 0x10 {
249	                    let target = m.funcs.get(i.a as usize).ok_or("unknown function index")?;
250	                    &m.types[target.type_idx as usize]
251	                } else {
252	                    table(m)?;
253	                    if i.b != 0 { return Err("unknown indirect-call table index".into()); }
254	                    let t = m.types.get(i.a as usize).ok_or("unknown indirect-call type index")?;
255	                    s.pop(Some(I32))?; t
256	                };
257	                s.effect(&called.params, &called.results)?;
258	            }
