use crate::model::*;
use std::collections::BTreeSet;
use std::fmt::Write as _;

#[derive(Clone, Debug)]
pub struct Val {
    pub ty: Ty,
    pub v: String,
}
#[derive(Clone)]
struct Frame {
    kind: u32,
    height: usize,
    params: Vec<Ty>,
    results: Vec<Ty>,
    saved: Vec<Val>,
    slots: Vec<String>,
    label: String,
    end: String,
    other: String,
    outer: bool,
    used: bool,
    had_else: bool,
}
pub struct Emitter<'a> {
    pub m: &'a Module,
    pub body: String,
    allocas: String,
    pub decls: BTreeSet<String>,
    next: usize,
    stack: Vec<Val>,
    frames: Vec<Frame>,
    live: bool,
    locals: Vec<Ty>,
}
pub fn hex(s: &str) -> String {
    s.as_bytes().iter().map(|b| format!("{b:02x}")).collect()
}
fn ret_type(t: &FuncType) -> String {
    match t.results.len() {
        0 => "void".into(),
        1 => t.results[0].llvm().into(),
        _ => format!(
            "{{ {} }}",
            t.results
                .iter()
                .map(|t| t.llvm())
                .collect::<Vec<_>>()
                .join(", ")
        ),
    }
}
fn signature(t: &FuncType) -> String {
    t.params
        .iter()
        .enumerate()
        .map(|(j, t)| format!("{} %a{j}", t.llvm()))
        .collect::<Vec<_>>()
        .join(", ")
}
fn type_id(m: &Module, idx: u32) -> usize {
    m.types
        .iter()
        .position(|t| *t == m.types[idx as usize])
        .unwrap()
}
impl<'a> Emitter<'a> {
    fn new(m: &'a Module) -> Self {
        Self {
            m,
            body: String::new(),
            allocas: String::new(),
            decls: BTreeSet::new(),
            next: 0,
            stack: vec![],
            frames: vec![],
            live: true,
            locals: vec![],
        }
    }
    fn name(&mut self) -> String {
        let n = self.next;
        self.next += 1;

